import type { Theme, ThemeOptions } from "@types";

import defaultTheme from "../bundled-themes/default";

import { handleThemeMerge } from "./create-theme-without-default";

export function createTheme<T extends Theme = Theme>(themeConfig: ThemeOptions<T>): T;
export function createTheme<T extends Theme = Theme>(
  baseTheme: T,
  newThemeConfig: ThemeOptions<T>,
): T;
export function createTheme<T extends Theme = Theme>(
  themeOrConfig: T | ThemeOptions<T>,
  newConfig?: ThemeOptions<T>,
): T {
  if (newConfig !== undefined) {
    const baseTheme = themeOrConfig as T;
    const customTheme = newConfig;
    return handleThemeMerge(baseTheme, customTheme);
  }

  const customTheme = themeOrConfig as ThemeOptions<T>;
  return handleThemeMerge(defaultTheme as T, customTheme);
}
